node -e "
const d = JSON.parse(require('fs').readFileSync('.devcontainer/keycloak/imports/startuphafen.json','utf8'));
console.log('realm:', d.realm);
console.log('clients:', d.clients.map(c => c.client_id));
console.log('users:', d.users.map(u => u.username));
console.log('themes attr:', JSON.stringify(d.attributes && d.attributes.theme));
const loginTheme = d.attributes && d.attributes.theme;
console.log('top-level keys:', Object.keys(d).filter(k=>!Array.isArray(d[k])).join(', '));
"

